import { html, slotted, when } from '../../@microsoft/fast-element/dist/esm/index.js';
import { startSlotTemplate, endSlotTemplate } from '../../utils/start-end-template.js';

function windowsTemplate() {
    return html `
		<div role="navigation" aria-label=${(x) => x.a11yAriaLabel}>
			<div class="windows" part="windows" role="grid">
				${startSlotTemplate()}
				<div class="tablist" part="tablist" role="row">
					<slot name="tab" ${slotted('tabs')}></slot>
					${when((x) => x.addable, html `
							<saf-tooltip anchor="add" part="add-tooltip" aria-hidden="true"
								>${(x) => x.addAriaLabel}</saf-tooltip
							>
							<saf-button
								nested-item
								id="add"
								class="add-window-button"
								part="add-window-button"
								appearance="tertiary"
								icon-only="true"
								@click="${(x) => x.add()}"
								density="compact"
								a11y-aria-label="${(x) => x.addAriaLabel}"
							>
								<saf-icon icon-name="plus"></saf-icon>
							</saf-button>
						`)}
				</div>
				${endSlotTemplate()}
			</div>
		</div>
		<div class="tabpanel" part="tabpanel">
			<slot name="tabpanel" ${slotted('tabpanels')}></slot>
		</div>
	`;
}

export { windowsTemplate };
